def priority(item: float, bins: np.ndarray) -> np.ndarray:
    valid = bins >= item
    if not np.any(valid):
        return np.full_like(bins, -np.inf)
    scale = np.mean(bins[valid]) / (np.std(bins[valid]) + 1e-12)
    target_ratio = 0.3 + 0.2 * np.arctan(scale) / (np.pi / 2)
    target = bins * target_ratio
    priority_vals = -np.abs(item - target)
    priority_vals[~valid] = -np.inf
    return priority_vals

